<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/includes/app/bootstrap.php';
require_permission('purchase_orders.view');
$orders=data_visible_collection('purchase_orders');$search=strtolower(query_string('q'));$status=query_string('status');
$orders=array_values(array_filter($orders,static function(array $po)use($search,$status):bool{if($search!==''&&!str_contains(strtolower($po['po_number'].' '.data_supplier_name($po['supplier_id'])),$search))return false;if($status!==''&&$po['status']!==$status)return false;return true;}));
$orders=sort_records($orders,'order_date','desc');$pagination=paginate_records($orders,query_int('page',1),8);
$visibleOrderIds=array_map('intval',array_column(data_visible_collection('purchase_orders'),'id'));$lines=array_values(array_filter(data_collection('purchase_order_lines'),fn(array $line):bool=>in_array((int)$line['purchase_order_id'],$visibleOrderIds,true)));$actions='<a class="button secondary" href="'.h(app_url('demand.php')).'">Demand & Requisitions</a>';if(can('purchase_orders.create'))$actions.='<button class="button primary" data-modal-open="poModal" type="button">Create Purchase Order</button>';
render_app_start('Purchase Orders','purchase-orders','Commitment visibility','Track purchase orders, line items, delivery dates, open commitments, buyer ownership, and review approvals.',$actions);
?>
<section class="metric-grid metric-grid-4"><article class="metric-card"><span>Visible orders</span><strong><?= count(data_visible_collection('purchase_orders')) ?></strong><small><?= h(current_scope_label()) ?></small></article><article class="metric-card"><span>Open commitment</span><strong><?= compact_money(data_dashboard_metrics()['open_commitments']) ?></strong><small>Open and past-due</small></article><article class="metric-card"><span>Past due</span><strong><?= count(array_filter(data_visible_collection('purchase_orders'),fn($p)=>$p['status']==='past_due')) ?></strong><small>Needs supplier escalation</small></article><article class="metric-card"><span>Pending review</span><strong><?= count(array_filter(data_visible_collection('purchase_orders'),fn($p)=>in_array($p['review_status'],['submitted','changes_requested'],true))) ?></strong><small>Workflow queue</small></article></section>
<section class="panel"><header class="panel-head"><div><span class="eyebrow">Purchase commitment control</span><h2>Purchase orders</h2></div><span class="panel-meta"><?= $pagination['total'] ?> matching orders</span></header><form class="filter-bar" method="get"><label><span>Search</span><input name="q" value="<?= h(query_string('q')) ?>" placeholder="PO number or supplier"></label><label><span>Status</span><select name="status"><option value="">All statuses</option><?php foreach(['draft','open','partially_received','past_due','closed','canceled'] as $value): ?><option value="<?= h($value) ?>" <?= $status===$value?'selected':'' ?>><?= h(status_label($value)) ?></option><?php endforeach; ?></select></label><button class="button secondary" type="submit">Apply filters</button><a class="button ghost" href="<?= h(app_url('purchase-orders.php')) ?>">Reset</a></form><div class="table-wrap"><table class="data-table" data-table><caption class="sr-only">Purchase orders for <?= h(current_scope_label()) ?></caption><thead><tr><th scope="col" data-sort>PO</th><th scope="col" data-sort>Company / supplier</th><th scope="col" data-sort>Dates</th><th scope="col" data-sort>Buyer</th><th scope="col" data-sort>Status</th><th scope="col" class="numeric" data-sort>Amount</th><th scope="col">Workflow</th></tr></thead><tbody><?php foreach($pagination['items'] as $po): $poLines=array_values(array_filter($lines,fn($line)=>(int)$line['purchase_order_id']===(int)$po['id'])); ?><tr><td><strong><?= h($po['po_number']) ?></strong><small><?= count($poLines) ?> line item(s) <?= sample_badge() ?></small></td><td><strong><?= h(data_company_name($po['company_id'])) ?></strong><small><?= h(data_supplier_name($po['supplier_id'])) ?></small></td><td><span>Ordered <?= h(date_us($po['order_date'])) ?></span><small>Expected <?= h(date_us($po['expected_date'])) ?></small></td><td><?= h(data_user_name($po['buyer_id'])) ?></td><td><?= badge($po['status']) ?><small><?= badge($po['review_status']) ?></small></td><td class="numeric"><strong><?= money($po['total_amount']) ?></strong></td><td><?= workflow_actions('purchase_orders',(int)$po['id'],$po['review_status'],'purchase_orders','purchase-orders.php') ?></td></tr><?php endforeach; ?><?php if(!$pagination['items']): ?><tr><td colspan="7"><?php render_empty_state('No purchase orders found','Adjust the filters or select another permitted company scope.'); ?></td></tr><?php endif; ?></tbody></table></div><?= render_pagination($pagination,['q'=>query_string('q'),'status'=>$status]) ?></section>
<section class="panel"><header class="panel-head"><div><span class="eyebrow">Line-level visibility</span><h2>Purchase-order line items</h2></div><span class="panel-meta"><?= count($lines) ?> sample lines</span></header><div class="table-wrap"><table class="data-table" data-table><caption class="sr-only">Purchase-order line items for <?= h(current_scope_label()) ?></caption><thead><tr><th scope="col" data-sort>PO</th><th scope="col" data-sort>Item / description</th><th scope="col" class="numeric" data-sort>Quantity</th><th scope="col" class="numeric" data-sort>Unit cost</th><th scope="col" class="numeric" data-sort>Line total</th></tr></thead><tbody><?php foreach($lines as $line): $po=data_find('purchase_orders',$line['purchase_order_id']); if(!$po||!data_record_visible($po))continue; ?><tr><td><strong><?= h($po['po_number']) ?></strong></td><td><?= h($line['description']) ?><small><?= h(data_item_name($line['item_id'])) ?></small></td><td class="numeric"><?= number_format($line['quantity']) ?></td><td class="numeric"><?= money($line['unit_cost']) ?></td><td class="numeric"><strong><?= money($line['line_total']) ?></strong></td></tr><?php endforeach; ?><?php if(!$lines): ?><tr><td colspan="5"><?php render_empty_state('No line items','No purchase-order lines are visible in this scope.'); ?></td></tr><?php endif; ?></tbody></table></div></section>
<?php if(can('purchase_orders.create')): ?><div class="modal" id="poModal" hidden><div class="modal-backdrop" data-modal-close></div><section class="modal-card"><header><div><span class="eyebrow">New purchase order</span><h2>Create purchase order</h2></div><button type="button" data-modal-close>×</button></header><form class="modal-body form-grid" action="<?= h(app_url('action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_purchase_order"><input type="hidden" name="return_to" value="purchase-orders.php"><label><span>PO number</span><input name="po_number" required value="PO-<?= str_pad((string)data_next_id('purchase_orders'),5,'0',STR_PAD_LEFT) ?>"></label><label><span>Company</span><select name="company_id"><?= company_options(current_company_id()==='enterprise'?1:current_company_id()) ?></select></label><label><span>Supplier</span><select name="supplier_id"><?= supplier_options(1) ?></select></label><label><span>Buyer</span><select name="buyer_id"><?= user_options(current_user()['id']) ?></select></label><label><span>Order date</span><input type="date" name="order_date" required value="<?= h(date('Y-m-d')) ?>"></label><label><span>Required date</span><input type="date" name="required_date" required value="<?= h(date('Y-m-d',strtotime('+14 days'))) ?>"></label><label><span>Expected date</span><input type="date" name="expected_date" required value="<?= h(date('Y-m-d',strtotime('+14 days'))) ?>"></label><label><span>Status</span><select name="status"><option value="draft">Draft</option><option value="open">Open</option></select></label><label class="span-2"><span>Total amount</span><input type="number" min="0" step="0.01" name="total_amount" value="0" required></label><div class="span-2 modal-actions"><button class="button secondary" type="button" data-modal-close>Cancel</button><button class="button primary" type="submit">Create purchase order</button></div></form></section></div><?php endif; ?>
<?php render_app_end(); ?>